const ITEM_BY_ID = new Map(ITEM_CATALOG.map(item => [item.id, item]));

export class ItemCatalog {
    static all() { return ITEM_CATALOG; }
    static categories() { return ITEM_CATEGORIES; }
    static get(id) { return ITEM_BY_ID.get(this.normalizeId(id)) || null; }
    static normalizeId(id) { const raw = String(id || "").trim().toLowerCase(); return raw.includes(":") ? raw : `minecraft:${raw}`; }
    static forMode(mode = "any") {
        if (mode === "contract") return ITEM_CATALOG.filter(i => i.contractable && !i.adminOnly);
        if (mode === "market") return ITEM_CATALOG.filter(i => i.marketable && !i.adminOnly);
        return ITEM_CATALOG;
    }
    static search(query = "", { mode = "any", category = null, limit = 5000 } = {}) {
        const q = String(query || "").trim().toLowerCase().replace(/^minecraft:/, "").replace(/[_-]+/g, " ");
        let pool = this.forMode(mode); if (category) pool = pool.filter(i => i.category === category);
        if (!q) return pool.slice(0, Math.max(1, Math.min(5000, limit)));
        const scored = [];
        for (const item of pool) {
            const id = item.id.replace("minecraft:", "").replace(/_/g, " "); const name = String(item.name || "").toLowerCase();
            const aliases = (item.aliases || []).map(a => String(a).toLowerCase()); let score = 0;
            if (id === q || item.id === `minecraft:${q}`) score = 100; else if (name === q) score = 95; else if (name.startsWith(q)) score = 80; else if (aliases.some(a => a === q)) score = 75; else if (id.startsWith(q)) score = 65; else if (name.includes(q)) score = 55; else if (id.includes(q)) score = 45; else if (aliases.some(a => a.includes(q))) score = 35;
            if (score) scored.push({ item, score });
        }
        scored.sort((a,b) => b.score - a.score || a.item.name.localeCompare(b.item.name));
        return scored.slice(0, Math.max(1, Math.min(5000, limit))).map(x => x.item);
    }
    static isAllowed(id, mode = "any") { const item = this.get(id); return !!item && (mode === "market" ? item.marketable && !item.adminOnly : mode === "contract" ? item.contractable && !item.adminOnly : true); }
}

export default ItemCatalog;
